import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    if r == 0 or c == 0:
        print(0)
        return
    g = bytearray()
    for i in range(r):
        g.extend(int(ch) for ch in data[2 + i])
    best = 0
    for s in range(r * c):
        if g[s] == 1:
            g[s] = 0
            stack = [s]
            area = 0
            while stack:
                u = stack.pop()
                area += 1
                y, x = divmod(u, c)
                if y > 0 and g[u - c]:
                    g[u - c] = 0; stack.append(u - c)
                if y < r - 1 and g[u + c]:
                    g[u + c] = 0; stack.append(u + c)
                if x > 0 and g[u - 1]:
                    g[u - 1] = 0; stack.append(u - 1)
                if x < c - 1 and g[u + 1]:
                    g[u + 1] = 0; stack.append(u + 1)
            if area > best:
                best = area
    print(best)

