    def fmt(rows):
        if not rows:
            return '0 0'
        return '%d %d\n%s' % (len(rows), len(rows[0]), '\n'.join(rows))
    def rnd(r, c, p):
        return [''.join('1' if rng.random() < p else '0' for _ in range(c)) for _ in range(r)]
    tests = [
        fmt([]),
        fmt(['0']),
        fmt(['1']),
        fmt(['11001', '10001', '00111', '11101']),
        fmt(['101', '010', '101']),
        fmt(['0000', '0000']),
        fmt(['1111', '1111', '1111']),
        fmt(['1', '1', '0', '1']),
        fmt(['10101']),
    ]
    for r, c in ((2, 2), (3, 3), (3, 5), (5, 3), (4, 4), (5, 5), (6, 6), (1, 8), (8, 1), (7, 9), (10, 10)):
        for p in (0.35, 0.55, 0.7):
            if r * c <= 80 or p == 0.55:
                tests.append(fmt(rnd(r, c, p)))
    N = 700
    tests.append(fmt(['1' * N for _ in range(N)]))
    tests.append(fmt(rnd(N, N, 0.6)))
    snake = []
    for i in range(N):
        if i % 2 == 0:
            snake.append('1' * N)
        elif i % 4 == 1:
            snake.append('0' * (N - 1) + '1')
        else:
            snake.append('1' + '0' * (N - 1))
    tests.append(fmt(snake))
    tests.append(fmt(rnd(N, N, 0.45)))
    return tests

